function narrationButton(id){const clip=narrationClips[id];return clip?`<button class="narration-button" type="button" data-narration="${id}" aria-label="Listen to two-voice narration">▶ <span>Listen</span><small data-idle-label="Two voices · Shore & Season">Two voices · Shore & Season</small></button>`:'';}
function narrationTranscript(id){const clip=narrationClips[id];return clip?`<details class="narration-transcript"><summary>Read the narration</summary><p>${escapeHtml(clip.text)}</p></details>`:'';}
function stopNarration(){if(activeNarrationAudio){activeNarrationAudio.pause();activeNarrationAudio=null;}if('speechSynthesis'in window)window.speechSynthesis.cancel();if(activeNarrationButton?.isConnected){activeNarrationButton.classList.remove('playing');activeNarrationButton.querySelector('span').textContent='Listen';const small=activeNarrationButton.querySelector('small');if(small)small.textContent=small.dataset.idleLabel||'Shore & Season narration';activeNarrationButton.setAttribute('aria-label','Listen to narration');}activeNarrationButton=null;}
function speakNarration(button,clip){
  if(!('speechSynthesis'in window)){button.querySelector('span').textContent='Unavailable';const small=button.querySelector('small');if(small)small.textContent='Audio unavailable';return;}
  const utterance=new SpeechSynthesisUtterance(clip.text);utterance.lang='en-US';utterance.rate=.94;utterance.pitch=1;
  utterance.onend=utterance.onerror=()=>{if(activeNarrationButton===button)stopNarration();};
  activeNarrationButton=button;button.classList.add('playing');button.querySelector('span').textContent='Stop';button.setAttribute('aria-label','Stop narration');window.speechSynthesis.speak(utterance);
}
function playNarration(button,clip){
  if(activeNarrationButton===button){stopNarration();return;}
  stopNarration();
  const audio=new Audio(clip.file);audio.preload='none';activeNarrationAudio=audio;activeNarrationButton=button;
  audio.addEventListener('ended',()=>{if(activeNarrationAudio===audio)stopNarration();},{once:true});
  audio.addEventListener('error',()=>{if(activeNarrationAudio!==audio)return;activeNarrationAudio=null;const small=button.querySelector('small');if(small)small.textContent='Device voice fallback';speakNarration(button,clip);},{once:true});
  button.classList.add('playing');button.querySelector('span').textContent='Loading';button.setAttribute('aria-label','Stop narration');
  audio.play().then(()=>{if(activeNarrationAudio===audio)button.querySelector('span').textContent='Stop';}).catch(()=>{if(activeNarrationAudio===audio){activeNarrationAudio=null;const small=button.querySelector('small');if(small)small.textContent='Device voice fallback';speakNarration(button,clip);}});
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-narration]');if(!button)return;
  event.preventDefault();const clip=narrationClips[button.dataset.narration];if(!clip)return;
  playNarration(button,clip);
});
