  let ids=Array.isArray(set)?set.slice():set?.[floridaAreaOf(s)]||set?.south||[];
  ids=ids.filter((id,index)=>id!==s.id&&ids.indexOf(id)===index&&stories.some(item=>item.id===id&&item.recipe)).slice(0,6);
  if(!ids.length)return '';
