function menuIngredients(){const courses=selectedMenuItems().flatMap(({option})=>{const story=option.storyId?stories.find(s=>s.id===option.storyId):null;const items=story?.recipe?.ingredients||option.ingredients.filter(item=>!item.startsWith('Use the '));const base=story?.recipe?.yield||'6 servings';return items.map(item=>scaleIngredient(item,mealServings,base));});const additions=feastRecipeIds.flatMap(id=>{const story=stories.find(s=>s.id===id);return story?.recipe?.ingredients.map(item=>scaleIngredient(item,mealServings,story.recipe.yield))||[];});return [...new Set([...courses,...additions])];}
