function mealBuilder(){const plan=mealPlans[mealArea],courses=selectedMenuItems(),market=menuIngredients();const saved=feastRecipeIds.map(id=>stories.find(s=>s.id===id)).filter(Boolean);return `<div class="share-backdrop meal-backdrop" id="meal-backdrop"><article class="meal-dialog" role="dialog" aria-modal="true" aria-labelledby="meal-title"><button id="meal-close" class="modal-close" aria-label="Close meal builder">×</button><div class="meal-cover"><span class="meal-orbit">✳</span><span class="eyebrow">BUILD A LOCAL TABLE</span><h2 id="meal-title">A meal with a sense of place.</h2><p>${escapeHtml(plan.intro)}</p><label class="meal-area-label">CHOOSE YOUR TABLE<select id="meal-area">${Object.entries(mealPlans).map(([id,item])=>`<option value="${id}" ${id===mealArea?'selected':''}>${escapeHtml(item.label)}</option>`).join('')}</select></label></div><div class="meal-content"><div class="meal-location"><span>✳ &nbsp; ${escapeHtml(plan.place)}</span><label>SERVES <input id="meal-servings" type="number" min="1" max="24" value="${mealServings}" aria-label="Number of servings"></label></div><div class="meal-courses">${courses.map(({course,option},index)=>{const story=option.storyId?stories.find(s=>s.id===option.storyId):null;const detail=story?.recipe;const ingredients=(detail?.ingredients||option.ingredients).map(item=>scaleIngredient(item,mealServings,detail?.yield||'6 servings'));const steps=detail?.steps||option.steps||[];return `<section class="meal-course"><div class="meal-course-top"><span class="meal-course-number">${String(index+1).padStart(2,'0')}</span><label><span>${escapeHtml(course.label)}</span><select data-meal-course="${course.id}" aria-label="Choose ${escapeHtml(course.label)}">${course.options.map(item=>`<option value="${item.id}" ${item.id===option.id?'selected':''}>${escapeHtml(item.title)}</option>`).join('')}</select></label></div><div class="meal-course-detail"><span class="meal-tag">${escapeHtml(option.tag)}</span><p>${escapeHtml(option.description)}</p>${ingredients.length?`<div class="meal-ingredients"><strong>GATHER · FOR ${mealServings}</strong><ul>${ingredients.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul></div>`:''}${steps.length?`<details class="meal-method"><summary>See the simple method</summary><ol>${steps.map(step=>`<li>${escapeHtml(step)}</li>`).join('')}</ol></details>`:''}${story?`<button type="button" class="meal-source-link" data-meal-story="${story.id}">Open full recipe & source ↗</button>`:`<span class="meal-source-note">${escapeHtml(option.source||'Modern Shore & Season idea')}</span>`}</div></section>`;}).join('')}</div><section class="feast-recipes"><div><span class="eyebrow">ADDED FROM RECIPE CARDS</span><h3>Your feast recipes</h3></div>${saved.length?saved.map(s=>`<article><div><strong>${escapeHtml(s.title)}</strong><span>${escapeHtml(s.kind)} · quantities scaled to ${mealServings} servings</span></div><button type="button" data-remove-feast="${s.id}" aria-label="Remove ${escapeHtml(s.title)}">Remove</button></article>`).join(''):'<p>Open any recipe and choose “Add to feast” to include it here.</p>'}</section><aside class="meal-care"><strong>PLACE & SOURCE NOTE</strong><p>${escapeHtml(plan.note)}</p>${mealArea==='atlantic'?`<a href="https://www.nps.gov/casa/learn/historyculture/the-first-thanksgiving.htm" target="_blank" rel="noopener noreferrer">Read the National Park Service account of 1565 ↗</a>`:''}</aside><section class="meal-market"><div><span class="eyebrow">YOUR MARKET BASKET · ${mealServings} SERVINGS</span><h3>${new Set(market).size} ingredients, one table.</h3><details><summary>Preview combined list</summary><ul>${market.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul></details><p>Recipe quantities scale by the serving count. Check linked sources and packaged sizes before shopping.</p></div><div class="meal-actions"><button id="meal-copy-list" type="button">Copy grocery list</button><button id="meal-add-shopping" type="button">Add menu to shopping list</button><button id="meal-share" type="button">Share this menu ↗</button></div><div id="meal-status" role="status"></div></section><p class="meal-footer">Check linked recipes for full directions, servings, allergens, and current source details. Turkey temperature: <a href="https://ask.fsis.usda.gov/article/What-is-the-internal-temperature-and-cooking-time-for-turkey" target="_blank" rel="noopener noreferrer">USDA FSIS guidance ↗</a></p></div></article></div>`;}
function walkthroughChapters(){
  let candidates=stories.filter(s=>(activeRegion==='all'||s.region===activeRegion)&&(activeRegion!=='florida'||activeFloridaArea==='all'||floridaAreaOf(s)===activeFloridaArea));
  if(!candidates.length)candidates=stories;
  const place=activeRegion==='florida'&&activeFloridaArea!=='all'?floridaAreas.find(a=>a.id===activeFloridaArea)?.label:regions.find(r=>r.id===activeRegion)?.label||'the East Coast';
  let history=candidates.find(s=>['st-augustine-1565','timucua-seloy-foodways'].includes(s.id))||candidates.find(s=>!s.recipe)||candidates[0];
  let recipes=candidates.filter(s=>s.recipe&&s.id!==history?.id);
  if(activeRegion==='florida'&&activeFloridaArea==='atlantic')recipes=['timucua-smoked-fish-pot','st-augustine-cocido','pumpkin-frybread'].map(id=>stories.find(s=>s.id===id)).filter(Boolean);
  recipes=recipes.slice(0,2);
  const foodStories=activeRegion==='all'?['florida','southeast','midatlantic','northeast','greatlakes'].flatMap(regionId=>{const local=candidates.filter(s=>s.region===regionId);return [...local.filter(s=>s.recipe),...local.filter(s=>!s.recipe)];}):[...candidates.filter(s=>s.recipe),...candidates.filter(s=>!s.recipe)];
  const foodThreads=[],seenFoods=new Set();
  for(const story of foodStories){for(const ingredient of story.ingredients||[]){const key=ingredient.trim().toLowerCase();if(!key||/^(water|salt|pepper|oil)$/i.test(key)||seenFoods.has(key))continue;seenFoods.add(key);foodThreads.push({name:ingredient,region:story.region,place:regions.find(r=>r.id===story.region)?.label||story.place});if(foodThreads.length>=6)break;}if(foodThreads.length>=6)break;}
  const openingArt=activeRegion==='florida'?{image:'/florida-foodways.webp',alt:'Illustrated Florida wetlands and seasonal foods'}:activeRegion==='northeast'?{image:'/northeast-foodways.webp',alt:'Illustrated Northeast coast and harvest foods'}:activeRegion==='midatlantic'?{image:'/chesapeake-foodways.webp',alt:'Illustrated Chesapeake waterways and harvest foods'}:{image:'/harvest-foodways.webp',alt:'Illustrated regional harvest landscape'};
  return [{title:activeRegion==='all'?'Follow a foodway':`Follow the ${place} foodway`,label:`A FOODWAYS FIELD WALK · ${place}`,description:'Trace one local ingredient from place to story to recipe. Every stop names its source and community; choose a food thread to make the trail yours.',foods:foodThreads,narration:'foodways-field-walk',...openingArt,story:null},...(history?[{title:history.title,label:`${history.place} · ${history.nation}`,description:history.description,image:storyImage(history).src,alt:storyImage(history).alt,story:history}]:[]),...recipes.map(s=>({title:s.title,label:`${s.place} · ${s.kind}`,description:s.description,image:storyImage(s).src,alt:storyImage(s).alt,story:s})),{title:'Bring a story to your table',label:'TRAIL END · YOUR TABLE',description:'Choose a source-linked recipe, add it to your feast, and gather its ingredients into one shareable market basket.',image:openingArt.image,alt:openingArt.alt,ending:true,story:null}];
}
function walkthroughRouteHTML(chapter){const active=chapter.ending?4:chapter.story?.recipe?3:chapter.story?2:1;const stages=['Place','Food','Story','Recipe','Table'];return `<ol class="walkthrough-route" aria-label="Foodways trail stages">${stages.map((label,index)=>`<li class="${index<active?'complete':index===active?'current':''}"${index===active?' aria-current="step"':''}><span>${index<active?'✓':String(index+1).padStart(2,'0')}</span><small>${label}</small></li>`).join('')}</ol>`;}
function walkthroughHTML(){const chapters=walkthroughChapters(),chapter=chapters[Math.min(walkthroughStep,chapters.length-1)];return `<div class="walkthrough-backdrop" id="walkthrough-backdrop"><section class="walkthrough-dialog" role="dialog" aria-modal="true" aria-labelledby="walkthrough-title"><button type="button" class="walkthrough-close" id="walkthrough-close" aria-label="Exit story walk">×</button><div class="walkthrough-art"><img src="${escapeHtml(chapter.image)}" alt="${escapeHtml(chapter.alt)}"><span class="walkthrough-art-mark">✳</span><div class="walkthrough-map-stamp"><span>FOODWAYS TRAIL</span><b>${String(walkthroughStep+1).padStart(2,'0')} <i>/</i> ${String(chapters.length).padStart(2,'0')}</b></div></div><div class="walkthrough-content"><div class="walkthrough-progress"><span>${escapeHtml(chapter.label)}</span><span>${String(walkthroughStep+1).padStart(2,'0')} / ${String(chapters.length).padStart(2,'0')}</span></div><div class="walkthrough-meter" aria-hidden="true"><i style="width:${((walkthroughStep+1)/chapters.length)*100}%"></i></div>${walkthroughRouteHTML(chapter)}<div class="walkthrough-reading"><h2 id="walkthrough-title">${escapeHtml(chapter.title)}</h2><p>${escapeHtml(chapter.description)}</p>${chapter.foods?.length?`<div class="walkthrough-food-threads"><div><span>CHOOSE A FOOD THREAD</span><small>Tap one to explore its recipes</small></div><div class="walkthrough-food-grid">${chapter.foods.map(food=>`<button type="button" data-walkthrough-ingredient="${escapeHtml(food.name)}" data-walkthrough-region="${escapeHtml(food.region)}"><b>✳</b><span>${escapeHtml(food.name)}</span><small>${escapeHtml(food.place)}</small><i>↗</i></button>`).join('')}</div></div>`:''}${chapter.ending?`<div class="walkthrough-completion"><span>✳ FIELD NOTES GATHERED</span><div><button type="button" data-walkthrough-explore>Explore recipes ↗</button><button type="button" data-walkthrough-share>Share this trail ↗</button></div></div>`:chapter.story?`<div class="walkthrough-source">${escapeHtml(chapter.story.kind)} <span>·</span> ${escapeHtml(chapter.story.nation)}</div><button type="button" class="walkthrough-open-story" data-walkthrough-story="${chapter.story.id}">Open story & sources ↗</button>`:`<div class="walkthrough-source">A short, optional guide · ${escapeHtml(regions.find(r=>r.id===activeRegion)?.label||'All coasts')}</div>`}<button type="button" id="walkthrough-listen" class="walkthrough-listen">♫ <span>Listen</span><small data-idle-label="Two voices · Field notes">Two voices · Field notes</small></button></div><div class="walkthrough-actions"><button type="button" id="walkthrough-back" ${walkthroughStep===0?'disabled':''}>← Back</button><button type="button" id="walkthrough-next">${walkthroughStep===chapters.length-1?'Finish trail ✳':'Follow the trail →'}</button></div><small class="walkthrough-disclaimer">Distinct peoples, distinct traditions. History is not recipe reconstruction.</small></div></section></div>`;}
function thanksgivingRootsDialog(){return `<dialog id="roots-key-dialog" class="about-dialog roots-key-dialog"><button type="button" id="roots-key-close" class="modal-close" aria-label="Close history key">×</button><span class="share-emblem">✳</span><div class="eyebrow">A SHORT HISTORY KEY</div><h2>${escapeHtml(thanksgivingRoots.title)}.</h2><p>${escapeHtml(thanksgivingRoots.intro)}</p><div class="roots-timeline">${thanksgivingRoots.chapters.map(chapter=>`<article><span>${escapeHtml(chapter.year)}</span><h3>${escapeHtml(chapter.title)}</h3><p>${escapeHtml(chapter.text)}</p><a class="external-source-direct" href="${escapeHtml(chapter.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(chapter.source)} ↗</a>${chapter.relatedUrl?`<a class="external-source-direct" href="${escapeHtml(chapter.relatedUrl)}" target="_blank" rel="noopener noreferrer">Smithsonian · Native perspectives ↗</a>`:''}</article>`).join('')}</div><section class="roots-living"><span class="eyebrow">${escapeHtml(thanksgivingRoots.livingTitle)}</span><p>${escapeHtml(thanksgivingRoots.livingText)}</p><a class="external-source-direct" href="${escapeHtml(thanksgivingRoots.livingUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(thanksgivingRoots.livingSource)} ↗</a></section><p class="roots-key-note">This guide distinguishes documented events, later national observances, and the living traditions of specific Native nations. Recipe cards keep their own community, place, status, and source attached.</p></dialog>`;}
function normalizePlaceText(value){return ` ${String(value).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()} `;}
function placeAliasMatches(name,normalizedQuery){const alias=normalizePlaceText(name);const term=alias.trim();if(!term)return false;if(term.length<=2)return normalizedQuery.split(/\s+/).includes(term);return normalizedQuery.includes(alias);}
function isPlaceSearch() {const q=normalizePlaceText(query);return q.trim().length>0&&Object.keys(placeAliases).some(name=>placeAliasMatches(name,q));}
function card(s) { const art=storyImage(s); return `<button class="story-card ${s.tone}${s.recipe?' recipe-story-card':''}" data-story="${s.id}" aria-label="Explore ${escapeHtml(s.title)}, roots, and sources"><span class="card-art ${s.recipe?'recipe-card-art':''}"><img src="${art.src}" alt="" loading="lazy"><span class="art-ring"></span><span class="art-symbol">${s.symbol}</span></span><span class="card-body"><span class="eyebrow">${escapeHtml(s.recipe?recipeStatusLabel(s):s.kind)} <span>·</span> ${escapeHtml(s.place)}</span><strong>${escapeHtml(s.title)}</strong><span class="card-description">${escapeHtml(s.description)}</span><span class="card-bottom"><span>${escapeHtml(s.nation)}</span><span class="card-roots-link">Roots & lore ↗</span></span></span></button>`; }
