async function share(kind){
  const {url,title,text}=sharePayload(),status=document.querySelector('#share-status');
  try{
    if(kind==='cast'){
      if(inMiniApp&&sdkInstance?.actions?.composeCast)await sdkInstance.actions.composeCast({text,embeds:[url]});
      else await openShareTarget(`https://farcaster.xyz/~/compose?text=${encodeURIComponent(text)}&embeds[]=${encodeURIComponent(url)}`);
    }else if(kind==='native'){
      if(navigator.share)await navigator.share({title,text,url});
      else if(await copyShareText(`${text}\n\n${url}`)){if(status)status.textContent='Invite copied. Paste it into any app to share.';return;}
      else throw new Error('Clipboard unavailable');
    }else if(kind==='x'){
      await openShareTarget(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`);
    }else if(kind==='email'){
      await openShareTarget(`mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(`${text}\n\n${url}`)}`);
    }else if(kind==='copy'){
      if(await copyShareText(url)){if(status)status.textContent='Share link copied.';return;}
      const field=document.querySelector('#share-link');field?.focus();field?.select();if(status)status.textContent='Select the link above and copy it.';return;
    }else if(kind==='copy-text'){
      if(await copyShareText(`${text}\n\n${url}`)){if(status)status.textContent='Invite message and link copied.';return;}
      const field=document.querySelector('#share-link');field?.focus();field?.select();if(status)status.textContent='Select the link above and copy it.';return;
    }
    const returnToGrocery=shareGrocery;shareOpen=false;shareMeal=false;shareGrocery=false;groceryOpen=returnToGrocery;render();
  }catch(error){if(error.name!=='AbortError'&&status)status.textContent=error.message||'Sharing unavailable. Copy the link above instead.';}
}
