import('@farcaster/miniapp-sdk').then(async ({sdk})=>{sdkInstance=sdk;try{inMiniApp=await sdk.isInMiniApp();if(inMiniApp){await sdk.actions.ready();sdk.back.onback=()=>dismissTopmostOverlay();syncMiniAppBack();}}catch(error){console.warn('Mini App initialization:',error);}}).catch(()=>{});


